# live/prod/app/terragrunt.hcl
include "root" { path = find_in_parent_folders("root.hcl") }
terraform { source = "git::https://git.acme/modules/app.git?ref=v1.6.0" }
dependency "vpc" { config_path = "../vpc" }
inputs = {
  vpc_id     = dependency.vpc.outputs.vpc_id
  subnet_ids = dependency.vpc.outputs.private_subnet_ids
}

dependency "vpc" {
  config_path = "../vpc"
  mock_outputs = {
    vpc_id             = "vpc-00000000"
    private_subnet_ids = ["subnet-00000000"]
  }
  mock_outputs_allowed_terraform_commands = ["validate", "plan"]
}

resource "spacelift_stack_dependency" "app_on_vpc" {
  stack_id            = spacelift_stack.app.id
  depends_on_stack_id = spacelift_stack.vpc.id
}
resource "spacelift_stack_dependency_reference" "vpc_id" {
  stack_dependency_id = spacelift_stack_dependency.app_on_vpc.id
  output_name         = "vpc_id"
  input_name          = "TF_VAR_vpc_id"
}
